modifications.process_replace:
result = state.get('result')
hid = state.get('head_id') or ''
tid = state.get('tail_id') or ''
text = state.get('text') or ''
head = state.get('head') or ''
tail = state.get('tail') or ''

if result == '$' and hid and tid:
    text_lower = text.lower()
    head_lower = head.lower()
    tail_lower = tail.lower()

    # Negation guard: if text explicitly negates causation near head or tail, override
    negation_phrases = [
        'did not cause', 'did not induce', 'did not result', 'did not lead',
        'no effect', 'not associated', 'not cause', 'not induce',
        'not result in', 'not lead to', 'failed to', 'unable to',
        'no evidence', 'not significant', 'does not cause', 'does not induce'
    ]
    override = False
    for phrase in negation_phrases:
        idx = text_lower.find(phrase)
        if idx == -1:
            continue
        for term in [head_lower, tail_lower]:
            if not term:
                continue
            tidx = text_lower.find(term)
            if tidx == -1:
                continue
            if abs(idx - tidx) <= 50:
                override = True
                break
        if override:
            break

    if not override:
        # Relaxed associative guard: only override if phrase within 30 chars
        associative_phrases = [
            'associated with', 'linked to', 'correlated with', 'related to',
            'risk factor', 'risk of', 'presumably', 'suggest', 'may', 'could',
            'possible', 'might', 'co-occurrence'
        ]
        for phrase in associative_phrases:
            idx = text_lower.find(phrase)
            if idx == -1:
                continue
            for term in [head_lower, tail_lower]:
                if not term:
                    continue
                tidx = text_lower.find(term)
                if tidx == -1:
                    continue
                if abs(idx - tidx) <= 30:
                    override = True
                    break
            if override:
                break

    if override:
        __result__ = []
    else:
        __result__ = [f"{hid} | {tid}"]
else:
    __result__ = []
